  ('viiri', 'viiri', '', '', '', '', 'fürhin', '[{"kategorie": "wörtlich", "text": "\"von hier nach vorne\" (Zusammensetzung aus der Präposition \"für\" und dem Adverb \"hin\")"}, {"kategorie": "allg.", "text": "hinfür, hinaus, hinvor"}]'::jsonb, ''),
  ('viira', 'viira', '', '', '', '', 'fürher', '[{"kategorie": "wörtlich", "text": "\"von dort hinten nach hier vorne\" (Zusammensetzung aus der Präposition \"für\" und dem Adverb \"her\")"}, {"kategorie": "allg.", "text": "hervor, heraus, nach vor"}]'::jsonb, 'si viiratraun'),
  ('proodaveigal', 'Proodaveigal', '', '', '', '', 'Praterveigerl', '[{"kategorie": "wörtlich", "text": "\"Praterveilchen\" (Determinativkompositum aus \"Prater\"=\"Wiener Praterau\" und \"Veigerl\"=\"Veilchen, das im Frühling überall im [[Wiener]] Prater blüht\")"}, {"kategorie": "scherzhaft für", "text": "billiges Strichmädchen, [[Praterhure]] (Prostituierte, die am [[Praterstrich]] anschaffen geht), [[Asphaltschwalbe]], [[Drossel]], [[Wetzen]], [[Hackenbraut]], [[Nudelfriedhof]]"}]'::jsonb, ''),
  ('wisawi', 'Wisawi', '', '', '', '', 'Vis--Vis', '[{"kategorie": "wörtlich", "text": "\"das Gegenüber\" (vom franzöisischen \"vis-[[-vis]]\"=\"gegenüber\")"}, {"kategorie": "allg.", "text": "gegenüberliegende Häuserfront, Bewohner des gegenüberliegenden Hauses"}, {"kategorie": "fig.", "text": "der/die Gegenübersitzende, der/die Gegenüberstehende, Gesprächspartner, Diskutant"}]'::jsonb, ''),
  ('wisawiwoonung', 'Wisawiwoonung', '', '', '', '', 'Vis--Vis-Wohnung', '[{"kategorie": "wörtlich", "text": "\"die gegenüberliegende Wohnung\" (Determinativkompositum aus \"vis-[[-vis]]\"=\"gegenüberliegend\" und \"Wohnung\"=\"Wohnstätte\")"}, {"kategorie": "allg.", "text": "\"die Nachbarwohnung gegenüber\", die Wohnung auf der anderen Seite des Ganges"}]'::jsonb, ''),
  ('voglheisl', 'Voglheisl', '', '', '', '', 'Vogelhäusel', '[{"kategorie": "wörtlich", "text": "\"Vogelhäuschen\" (Determinativkompositum aus \"Vogel\"=\"Singvogel\" und [[Heisl]]=\"Futterhäuschen\")"}, {"kategorie": "allg.", "text": "kleines Vogelhaus, Vogelfutterstelle, Nistkasten"}, {"kategorie": "Fußballerjargon, scherzhaft für", "text": "\"Weststadion\" (früher \"Hannappistadion\", heute [[Allianz Stadion]] = Heimstätte des SK [[Rapid]] Wien - in Anspielung darauf, dass im \"Weststadion\" immer ein starker Westwind blies, der früher für gehörig Zugluft innerhalb des Stadions sorgte)"}]'::jsonb, 'Do ziagds wiarin an Voglheisl'),
  ('austria', 'Austria', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Austria', '[{"kategorie": "wörtlich, kurz für", "text": "\"Fußballklub Austria Wien\" (bzw. [[FK Austria Wien]]) =  \"einer der erfolgreichsten und traditionsreichsten Fußballvereine in Österreich\" (oft einfach als [[Austria]] Wien oder [[Austria]] bezeichnet)"}, {"kategorie": "", "text": "Der Verein hat seinen Sitz im 10. Wiener Gemeindebezirk ([[Favoriten]]), gehört zu den bekanntesten Fußballclubs in Österreich und genießt sowohl national als auch international hohes Ansehen"}, {"kategorie": "", "text": "Der Fußballklub Austria Wien wurde am 15. März 1911 unter dem Namen „Wiener Amateur-Sportverein“ gegründet. 1926 änderte der Verein seinen Namen in „FK Austria Wien“, unter dem er bis heute bekannt ist"}, {"kategorie": "", "text": "Austria Wien trägt seine Heimspiele in der [[Generali-Arena]] aus, die sich im Stadtteil [[Favoriten]] befindet. Das Stadion wurde ursprünglich 1925 als Franz-Horr-Stadion eröffnet und wurde im Laufe der Jahre mehrfach modernisiert und erweitert. Nach umfangreichen Renovierungen in den Jahren 2016 bis 2018 bietet das Stadion nun Platz für etwa 17.500 Zuschauer"}, {"kategorie": "", "text": "Die Vereinsfarben von Austria Wien sind Violett und Weiß, weshalb die Mannschaft oft als à„die Veilchen“ bzw. [[die Violetten]] bezeichnet wird. Diese Farben sind tief in der Vereinsidentität verankert und finden sich sowohl im Logo als auch in den Trikots des Teams wieder. Das Vereinslogo zeigt die Initialen „FKA“ (für Fußballklub Austria) und das Gründungsjahr 1911 in einem violetten Kreis"}, {"kategorie": "", "text": "Eine der intensivsten und bekanntesten Rivalitäten im österreichischen Fußball besteht zwischen Austria Wien und dem Stadtrivalen [[SK]] Rapid Wien. Diese Spiele, bekannt als das à„Wiener Derby“, gehören zu den wichtigsten und emotionalsten Begegnungen im österreichischen Fußballkalender und ziehen immer viel Aufmerksamkeit auf sich"}]'::jsonb, 'Austria Wiin'),
  ('rapid', 'Rapid', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Rapid', '[{"kategorie": "wörtlich, kurz für", "text": "\"Sportklub Rapid Wien\" bzw. \"SK Rapid Wien\" = \"einer der ältesten, erfolgreichsten und traditionsreichsten Fußballvereine in Österreich\""}, {"kategorie": "", "text": "Der Verein wurde 1899 gegründet und hat seinen Sitz im 14. Wiener Gemeindebezirk ([[Penzing]]), im Stadtteil [[Hütteldorf]]. Rapid Wien gehört zu den bekanntesten Fußballclubs in Österreich und genießt auch international hohes Ansehen"}, {"kategorie": "", "text": "Der Sportklub Rapid wurde am 8. Jänner 1899 unter dem Namen „Erster Wiener Arbeiter-Fußball-Club“ gegründet und erhielt 1899 seinen heutigen Namen"}, {"kategorie": "", "text": "Der Verein trägt seine Heimspiele im [[Allianz-Stadion]] aus, das im Wiener Stadtteil [[Hütteldorf]] liegt und eine Kapazität von etwa 28.000 Zuschauern hat. Das Stadion, oft auch als à„Weststadion“ bezeichnet, ist ein zentraler Ort für die Fans des Vereins und bekannt für seine stimmungsvolle Atmosphäre"}, {"kategorie": "", "text": "Die Vereinsfarben von Rapid Wien sind Grün und Weiß, und diese Farben sind in der gesamten Vereinsidentität stark verankert. Das Vereinslogo zeigt einen grünen Schild mit einem weißen Querbalken, der die Vereinsinitialen \"S.K.\" und \"Rapid\" enthält, darüber sind drei Sterne, die für die nationalen Titel stehen"}, {"kategorie": "", "text": "Die Mannschaft wird häufig als à„die Grün-Weißen“ oder „die Hütteldorfer“ bezeichnet, und der Fankreis ist für seine große Leidenschaft und Treue bekannt. Die Fans von Rapid Wien, die „Rapidler“, gehören zu den lautstärksten und engagiertesten in Österreich"}, {"kategorie": "", "text": "Eine der intensivsten und bekanntesten Rivalitäten im österreichischen Fußball besteht zwischen dem SK Rapid Wien und dem Stadtrivalen [[FK]] Austria Wien. Diese Spiele, bekannt als das à„Wiener Derby“, gehören zu den wichtigsten und emotionalsten Begegnungen im österreichischen Fußballkalender und ziehen immer viel Aufmerksamkeit auf sich"}]'::jsonb, ''),
  ('westschdadion', 'Westschdadion', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Weststadion', '[{"kategorie": "allg.", "text": "\"modernes Fußballstadion im 14. Wiener Gemeindebezirk ([[Penzing]]), im Stadtteil [[Hütteldorf]] (offizieller Name: \"Allianz-Stadion\"). Es ist die Heimspielstätte des österreichischen Fußballvereins [[SK]] Rapid Wien, einem der erfolgreichsten und traditionsreichsten Fußballclubs des Landes"}, {"kategorie": "", "text": "Das Allianz-Stadion wurde auf dem Gelände des ehemaligen Gerhard-Hanappi-Stadions errichtet, das von 1977 bis 2014 als Heimstadion von Rapid Wien diente. Nach dem Abriss des alten Stadions wurde der Bau des neuen Stadions im Jahr 2014 begonnen und im Juli 2016 feierlich eröffnet"}, {"kategorie": "", "text": "Das Stadion verdankt seinen Namen dem Versicherungsunternehmen Allianz, das die Namensrechte erworben hat. Es wird jedoch unter Rapid-Fans jedoch zumeist als \"Weststadion\" bezeichnet, in Anlehnung an den früheren Namen und die geographische Lage im Westen Wiens"}, {"kategorie": "", "text": "Im Volksmund wurde das Weststadion früher auch als [[Voglheisl]] (\"Vogelhäuschen\") tituliert (in Anspielung darauf, dass im \"Weststadion\" immer ein starker Westwind blies, der früher für gehörig Zugluft innerhalb des Stadions sorgte)"}]'::jsonb, ''),
  ('baumgatn', 'Baumgatn', '', '', '', '', 'Baumgarten', '[{"kategorie": "allg.", "text": "Stadtteil im 14. Wiener Gemeindebezirk ([[Penzing]])"}, {"kategorie": "", "text": "Er liegt im Westen Wiens und gehört zu den eher ruhigen und grünen Wohngebieten der Stadt. Der Stadtteil ist durch seine historische Entwicklung, seine Wohnqualität und seine Nähe zum Wienerwald charakterisiert"}, {"kategorie": "", "text": "Baumgarten war ursprünglich ein eigenständiges Dorf und wurde erstmals im 12. Jahrhundert urkundlich erwähnt. Der Name „Baumgarten“ deutet auf die früher weit verbreiteten Obstgärten und Weinbauflächen in der Region hin"}, {"kategorie": "", "text": "m Jahr 1892 wurde Baumgarten nach Wien eingemeindet und ist seitdem Teil des 14. Bezirks, Penzing. In der Folge entwickelte sich Baumgarten zu einem dicht besiedelten Stadtteil mit einer Mischung aus Altbauten und modernen Wohnanlagen"}]'::jsonb, ''),
  ('hittlduaf', 'Hittlduaf', '', '', '', '', 'Hütteldorf', '[{"kategorie": "allg.", "text": "Stadtteil im 14. Wiener Gemeindebezirk ([[Penzing]]), im Westen Wiens, am Rande des [[Wienerwaldes]]"}, {"kategorie": "", "text": "Hütteldorf ist bekannt für seine ruhige Wohnlage, seine Nähe zur Natur und als Heimat des Fußballvereins [[SK]] Rapid Wien"}, {"kategorie": "", "text": "Hütteldorf wurde erstmals im 12. Jahrhundert urkundlich erwähnt und war ursprünglich ein kleines Dorf am Rande des Wienerwaldes. Im Laufe der Jahrhunderte entwickelte sich Hütteldorf von einer ländlichen Siedlung zu einem Vorort von Wien, bevor es 1892 gemeinsam mit anderen Vororten in die Stadt Wien eingemeindet wurde."}]'::jsonb, ''),
  ('braadnlee', 'Braadnlee', '', '', '', '', 'Breitenlee', '[{"kategorie": "allg.", "text": "Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]])"}, {"kategorie": "", "text": "Er liegt im nordöstlichen Teil Wiens und ist durch seine ländliche Atmosphäre, weite Grünflächen und ruhige Wohngebiete geprägt. Breitenlee ist einer der historisch älteren Teile des Bezirks und hat sich über die Jahre hinweg von einem ländlichen Dorf zu einem Teil des städtischen Wien entwickelt"}, {"kategorie": "", "text": "Breitenlee wurde erstmals im Jahr 1160 urkundlich erwähnt und war lange Zeit ein eigenständiges Dorf, das von Landwirtschaft und Weinbau geprägt war. Wie viele andere Vororte Wiens wurde Breitenlee im Zuge der Expansion der Stadt im Jahr 1938 nach Wien eingemeindet und ist seither Teil des 22. Bezirks, Donaustadt"}, {"kategorie": "", "text": "Breitenlee liegt im nördlichen Teil des 22. Bezirks und grenzt an die Stadtteile [[Essling]], [[Aspern]] und [[Süßenbrunn]] sowie an die niederösterreichische Ortschaft Raasdorf im Umland von Wien. Der Stadtteil erstreckt sich über eine flache Landschaft, die von Feldern und Wiesen geprägt ist. Diese Umgebung verleiht Breitenlee einen ländlichen Charme, trotz seiner Lage innerhalb der Stadtgrenzen Wiens."}]'::jsonb, ''),
  ('essling', 'Essling', '', '', '', '', 'Essling', '[{"kategorie": "allg.", "text": "Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]]), im östlichen Teil Wiens, nahe der Donau und den Donau-Auen"}, {"kategorie": "", "text": "Essling hat sich von einem historischen Dorf zu einem ruhigen und grünen Wohngebiet entwickelt und ist bekannt für seine ländliche Atmosphäre, historische Bedeutung und gute Lebensqualität"}, {"kategorie": "", "text": "Essling wurde erstmals im 12. Jahrhundert urkundlich erwähnt und war lange Zeit ein eigenständiges Dorf, das hauptsächlich von Landwirtschaft und Weinbau lebte. Der Stadtteil erlangte historische Bedeutung durch die Schlacht bei [[Aspern-Essling]] im Jahr 1809, in der Napoleon Bonaparte eine seiner ersten Niederlagen erlitt. Diese Schlacht war Teil der napoleonischen Kriege und wurde in der Umgebung der beiden damals noch eigenständigen Dörfer Aspern und Essling ausgetragen"}, {"kategorie": "", "text": "Im Jahr 1938 wurde Essling im Zuge der Eingemeindung mehrerer Vororte nach Wien in den 22. Bezirk, Donaustadt, integriert. Trotz der Eingemeindung hat sich Essling viel von seinem dörflichen Charakter bewahrt."}]'::jsonb, ''),
  ('aspan', 'Aspan', '', '', '', '', 'Aspern', '[{"kategorie": "allg.", "text": "\"Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]]), im östlichen Teil Wiens\", nahe den [[Donau-Auen]] und dem [[Nationalpark]] Donau-Auen. Es grenzt an die Stadtteile [[Essling]], [[Breitenlee]] und [[Groß-Enzersdorf]]"}, {"kategorie": "", "text": "Aspern ist einer der historisch bedeutendsten und gleichzeitig einer der am schnellsten wachsenden Teile Wiens, bekannt für seine Verbindung von Geschichte, moderner Stadtentwicklung und naturnaher Umgebung"}, {"kategorie": "", "text": "Aspern wurde erstmals im Jahr 1258 urkundlich erwähnt und war ursprünglich ein eigenständiges Dorf. Es ist besonders bekannt für die [[Schlacht]] bei Aspern im Jahr 1809, eine der bedeutendsten Auseinandersetzungen in den Napoleonischen Kriegen. In dieser Schlacht erlitt Napoleon Bonaparte eine seiner ersten großen Niederlagen gegen die österreichischen Truppen unter Erzherzog Karl. Die Schlacht fand in der Umgebung der Dörfer Aspern und [[Essling]] statt und wird bis heute durch verschiedene Denkmäler in der Gegend, wie das [[Asperner]] Löwe-Denkmal, gewürdigt"}, {"kategorie": "", "text": "Im Jahr 1938 wurde Aspern in den 22. Bezirk eingemeindet und ist seither ein integraler Bestandteil Wiens. Trotz der Urbanisierung hat Aspern seinen historischen Charme und seine Verbindung zur ländlichen Vergangenheit bewahrt"}, {"kategorie": "", "text": "In den letzten Jahren ist Aspern vor allem durch die Entwicklung der [[Seestadt]] Aspern bekannt geworden, eines der größten Stadtentwicklungsprojekte in Europa. Die Seestadt Aspern ist ein neuer Stadtteil, der auf dem Gelände eines ehemaligen Flugplatzes errichtet wurde und Platz für zehntausende Menschen sowie zahlreiche Unternehmen bietet. Die Seestadt ist ein Paradebeispiel für moderne, nachhaltige Stadtentwicklung und zieht sowohl neue Einwohner als auch Investitionen an."}]'::jsonb, ''),
  ('kagran', 'Kagran', '', '', '', '', 'Kagran', '[{"kategorie": "allg.", "text": "Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]]), im nordöstlichen Teil von Wien. Kagran ist einer der größten und am schnellsten wachsenden Teile des Bezirks und spielt eine wichtige Rolle sowohl als Wohngebiet als auch als wirtschaftliches und kulturelles Zentrum der Donaustadt"}, {"kategorie": "", "text": "Kagran wurde erstmals im Jahr 1190 urkundlich erwähnt und war ursprünglich ein kleines Dorf, das vorwiegend von Landwirtschaft geprägt war. Im Laufe der Jahrhunderte wuchs Kagran langsam, blieb aber bis ins 20. Jahrhundert hinein relativ ländlich geprägt"}, {"kategorie": "", "text": "Mit der Eingemeindung nach Wien im Jahr 1904 und insbesondere nach dem Zweiten Weltkrieg begann Kagran, sich stark zu entwickeln. Der Bau neuer Wohnsiedlungen, Schulen und die Verbesserung der Verkehrsanbindung führten zu einem raschen Bevölkerungswachstum und zur Modernisierung des Stadtteils"}, {"kategorie": "", "text": "Heute ist Kagran ein bedeutender Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]]), der durch seine zentrale Lage, seine moderne Infrastruktur und seine vielfältigen Freizeit- und Einkaufsmöglichkeiten besticht. Als Wohnort und Wirtschaftsstandort hat Kagran eine wichtige Rolle in der Entwicklung der Donaustadt und ist ein dynamisches und lebendiges Zentrum im nordöstlichen Teil von Wien"}]'::jsonb, 'Kagrana Plotz'),
  ('heenschdrossn', 'Heenschdrossn', '', '', '', '', 'Höhenstraße', '[{"kategorie": "allg.", "text": "\"bekannte Panoramastraße, die sich durch die Hügel des [[Wienerwalds]] im Westen der Stadt schlängelt\""}, {"kategorie": "", "text": "Sie bietet eine beeindruckende Aussicht über Wien und das Umland"}, {"kategorie": "", "text": "Die Straße erstreckt sich von à[[Neuwaldegg]] im 17. Bezirk ([[Hernals]]) bis nach Klosterneuburg und führt durch mehrere Wiener Bezirke, darunter [[Döbling]] (19. Bezirk) und [[Währing]] (18. Bezirk)"}, {"kategorie": "", "text": "Die Höhenstraße wurde in den 1930er Jahren erbaut und ist eine der höchsten Straßen in Wien, weshalb sie auch diesen Namen trägt"}, {"kategorie": "", "text": "Die Straße ist großteils gesplastert und gut befahrbar, jedoch teilweise eng und kurvenreich, was sie besonders reizvoll für gemütliche Ausfahrten macht"}]'::jsonb, ''),
  ('dreimarkschdaa', 'Dreimarkschdaa', '', '', '', '', 'Dreimarkstein', '[{"kategorie": "allg.", "text": "\"454 Meter hoher Berg an der Grenze der Wiener Gemeindebezirke [[Döbling]] (19. Bezirk) und [[Hernals]] (17. Bezirk) sowie der niederösterreichischen Katastralgemeinde Weidling\""}, {"kategorie": "", "text": "Der Dreimarkstein ist ein Ausläufer des [[Wienerwaldes]] und setzt sich durch die [[Salmannsdorfer]] Höhe fort"}, {"kategorie": "", "text": "Der Berg ist größtenteils bewaldet, jedoch verläuft im Süden, knapp unterhalb des Gipfels, die [[Wiener]] Höhenstraße"}, {"kategorie": "", "text": "Der Name „Dreimarkstein“ leitet sich vom althochdeutschen \"marca\" und mittelhochdeutschen \"mark\" ab, was für Grenze oder abgegrenztes Land steht. Der Name verweist darauf, dass hier früher die Grenzen der Bezirke [[Hernals]], [[Döbling]] und [[Währing]] zusammenliefen. Nach der Abtretung von [[Salmannsdorf]] an [[Döbling]] treffen heute jedoch nur noch die Grenzen von Hernals, Döbling und Weidling aufeinander"}, {"kategorie": "", "text": "Der Dreimarkstein ist ein beliebtes Ausflugsziel für Wanderer und Naturliebhaber. Von hier aus bieten sich wunderschöne Ausblicke auf die Stadt Wien und die umliegenden Wälder"}]'::jsonb, ''),
  ('soimaunnsduaf', 'Soimaunnsduaf', '', '', '', '', 'Salmannsdorf', '[{"kategorie": "allg.", "text": "Stadtteil im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Es liegt am nordwestlichen Rand Wiens, direkt am Rande des [[Wienerwalds]], und ist bekannt für seine ruhige, ländliche Atmosphäre und seine gehobenen Wohngebiete"}, {"kategorie": "", "text": "Salmannsdorf gehört zu den traditionellen Heurigen-Gegenden Wiens, was bedeutet, dass der Weinbau und die typischen Wiener Weingasthäuser ([[Heurige]]) eine wichtige Rolle in der Geschichte und Kultur des Stadtteils spielen"}, {"kategorie": "", "text": "Der Stadtteil zeichnet sich durch seine Mischung aus historischen und modernen Wohnhäusern, Villen und Gärten aus"}, {"kategorie": "", "text": "Ein bekanntes Ausflugsziel in Salmannsdorf ist die [[Salmannsdorfer]] Höhe, eine Erhebung, von der aus man eine schöne Aussicht auf Wien und die umliegende Natur genießen kann"}, {"kategorie": "", "text": "In der Nähe liegt auch das Gasthaus [[Häuserl am Stoan]], das für seine traditionelle Wiener Küche und die malerische Lage geschätzt wird."}]'::jsonb, ''),
  ('heamaunnskogl', 'Heamaunnskogl', '', '', '', '', 'Hermannskogel', '[{"kategorie": "allg.", "text": "\"höchster Berg im Stadtgebiet von Wien\" (542m)"}, {"kategorie": "", "text": "Er liegt im nördlichen [[Wienerwald]], im 19. Bezirk ([[Döbling]]), und ist ein beliebtes Ausflugsziel für Wanderer, Naturliebhaber und Touristen"}, {"kategorie": "", "text": "Der Hermannskogel ist Teil der nördlichen Ausläufer des Wienerwalds und bietet einen weiten Blick über Wien und das Umland. Auf seinem Gipfel befindet sich die [[Habsburgwarte]], ein 27 Meter hoher Aussichtsturm, der im Jahr 1888 errichtet wurde. Die Habsburgwarte ermöglicht Besuchern einen noch besseren Ausblick über die Stadt und die umgebenden Landschaften"}, {"kategorie": "hist.", "text": "Der Hermannskogel hat auch eine historische Bedeutung: Bis 1920 galt er als der geodätische Ausgangspunkt für das österreichisch-ungarische Gradmessungsnetz und war somit ein wichtiger Referenzpunkt für die Landvermessung in der [[Habsburgermonarchie]]. Der sogenannte Triangulationspunkt Hermannskogel war ein zentraler Punkt des damaligen europäischen Vermessungsnetzes."}]'::jsonb, ''),
  ('habsbuagwartn', 'Habsbuagwartn', '', '', '', '', 'Habsburgwarte', '[{"kategorie": "allg.", "text": "historischer Aussichtsturm auf dem [[Hermannskogel]], dem höchsten Berg Wiens (542m), im 19. Bezirk ([[Döbling]])"}, {"kategorie": "", "text": "Der Turm wurde im Jahr 1888 vom Österreichischen Touristenklub errichtet und ist nach der Habsburger-Dynastie benannt, die Österreich über viele Jahrhunderte regierte"}, {"kategorie": "", "text": "Die Habsburgwarte ist 27 Meter hoch und besteht aus Stein. Sie bietet eine beeindruckende Aussicht über Wien und die umliegenden Gebiete des Wienerwalds. An klaren Tagen kann man von der Habsburgwarte aus bis weit ins [[Wiener]] Becken und die Alpen sehen"}, {"kategorie": "hist.", "text": "Die Habsburgwarte spielt auch eine historische Rolle, da sich auf dem Hermannskogel ein wichtiger Triangulationspunkt des ehemaligen österreichisch-ungarischen Vermessungsnetzes befindet, der als geodätischer Ausgangspunkt diente."}]'::jsonb, ''),
  ('kobenzl', 'Kobenzl', '', '', '', '', 'Cobenzl', '[{"kategorie": "allg.", "text": "bekanntes Ausflugsziel im 19. Wiener Gemeindebezirk ([[Döbling]]), das auf einer Anhöhe im [[Wienerwald]] liegt"}, {"kategorie": "", "text": "Der Name \"Cobenzl\" geht auf Johann Philipp von Cobenzl, einen österreichischen Staatsmann des 18. Jahrhunderts, zurück, der das Gut erwarb und es zu einem beliebten Treffpunkt der Wiener Gesellschaft machte"}, {"kategorie": "", "text": "Der Cobenzl ist über die [[Höhenstraße]] gut erreichbar und wird oft in Verbindung mit dem nahegelegenen [[Kahlenberg]] besucht, da beide Orte zu den klassischen Aussichtspunkten über Wien gehören. Die Lage im Grünen und die Kombination aus Natur, Kultur und Gastronomie machen den Cobenzl zu einem beliebten Ziel für Einheimische und Touristen"}]'::jsonb, ''),
  ('hiaschschdettn', 'Hiaschschdettn', '', '', '', '', 'Hirschstetten', '[{"kategorie": "allg.", "text": "Stadtteil im 22. Wiener Gemeindebezirk ([[Donaustadt]])"}, {"kategorie": "", "text": "Es handelt sich um ein traditionelles Siedlungsgebiet, das in den letzten Jahrzehnten eine starke städtebauliche Entwicklung erfahren hat. Hirschstetten liegt im östlichen Teil Wiens und kombiniert ländliche, dörfliche Strukturen mit modernen Wohnsiedlungen und Gewerbegebieten"}, {"kategorie": "", "text": "Historisch gesehen war Hirschstetten ursprünglich ein kleines Dorf, das bereits im Mittelalter existierte und später nach Wien eingemeindet wurde. Der ländliche Charakter des Stadtteils ist in einigen Teilen bis heute erhalten geblieben, insbesondere in den alten Dorfkernen und den umliegenden Feldern und Gärten"}, {"kategorie": "", "text": "Ein besonders bekanntes Merkmal von Hirschstetten sind die [[Blumengärten]] Hirschstetten, eine weitläufige Parkanlage und botanischer Garten, der von den Wiener Stadtgärten betrieben wird. Diese Gärten sind ein beliebtes Ausflugsziel und bieten neben einer Vielzahl von Themengärten auch einen Zoo und diverse Veranstaltungen, insbesondere zur Weihnachtszeit."}]'::jsonb, ''),
  ('wiinawoid', 'Wiinawoid', '', '', '', '', 'Wienerwald', '[{"kategorie": "allg.", "text": "\"großes, bewaldetes Gebiet, das sich über den nordöstlichen Teil der Alpen erstreckt und sich bis in die Stadt Wien erstreckt\""}, {"kategorie": "", "text": "Er bildet eine natürliche Grenze zwischen dem [[Wiener]] Becken und dem Alpenvorland und ist sowohl ein wichtiges Naherholungsgebiet als auch ein bedeutender Naturraum für die Region"}, {"kategorie": "", "text": "Der Wienerwald umfasst eine Fläche von etwa 1.200 Quadratkilometern und erstreckt sich über die Bundesländer Wien und Niederösterreich. Er ist durch hügelige Landschaften, dichte Wälder, Wiesen und zahlreiche Bäche und Flüsse geprägt. Die höchste Erhebung des Wienerwalds in Wien ist der [[Hermannskogel]] (542 m), der höchste Punkt Wiens"}, {"kategorie": "", "text": "Der Wienerwald ist als Biosphärenpark anerkannt und genießt besonderen Schutz aufgrund seiner ökologischen Bedeutung. Er ist Heimat einer vielfältigen Flora und Fauna, darunter zahlreiche geschützte Pflanzen- und Tierarten"}, {"kategorie": "", "text": "Das Gebiet ist geprägt von Mischwäldern mit Eichen, Buchen, Fichten und Tannen sowie von Auenlandschaften entlang der Flüsse"}, {"kategorie": "", "text": "Der Wienerwald spielt eine zentrale Rolle als \"grüne Lunge\" der Stadt Wien, er trägt zur Luftreinhaltung und zum Klimaschutz bei"}, {"kategorie": "", "text": "Bekannte Ausflugsziele im Wienerwald sind der [[Kahlenberg]], der [[Leopoldsberg]] und die [[Habsburgwarte]] auf dem [[Hermannskogel]]. Diese Orte bieten spektakuläre Ausblicke auf Wien und das Umland"}]'::jsonb, ''),
  ('kaisaebaschduaf', 'Kaisaebaschduaf', '', '', '', '', 'Kaiserebersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 11. Wiener Gemeindebezirk ([[Simmering]]) im Südosten von Wien\""}, {"kategorie": "", "text": "Es handelt sich um einen traditionsreichen Ort mit einer langen Geschichte, die bis ins Mittelalter zurückreicht. Der Stadtteil ist heute vor allem als Wohngebiet bekannt, hat aber auch historische und kulturelle Bedeutung"}, {"kategorie": "", "text": "Kaiserebersdorf wurde erstmals im 12. Jahrhundert urkundlich erwähnt. Der Name leitet sich von „Ebersdorf“ ab, wobei „Eber“ auf Wildschweine hinweist, die in den umliegenden Wäldern vorkamen. Der Zusatz „Kaiser-“ wurde später hinzugefügt, als die Habsburger die Region stärker in ihre Herrschaft einbanden"}, {"kategorie": "", "text": "Das Schloss Kaiserebersdorf, das im 16. Jahrhundert errichtet wurde, spielte eine bedeutende Rolle in der Geschichte des Stadtteils. Es diente lange Zeit als Jagdschloss der Habsburger, dann als Kaserne und wird heute als Strafanstalt (\"Justizanstalt Simmering\") genutzt. Vom ursprünglichen Schloss ist heute nur noch wenig erhalten"}, {"kategorie": "", "text": "Die [[Pfarrkirche]] St. Peter und Paul ist eine der Hauptsehenswürdigkeiten des Stadtteils. Sie wurde im 14. Jahrhundert erbaut und später im barocken Stil umgestaltet."}]'::jsonb, ''),
  ('gumpnduaf', 'Gumpnduaf', '', '', '', '', 'Gumpendorf', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 6. Wiener Gemeindebezirk ([[Mariahilf]])\""}, {"kategorie": "", "text": "Es handelt sich um eine der ältesten Siedlungen Wiens, deren Ursprünge bis ins Mittelalter zurückreichen. Gumpendorf war ursprünglich ein eigenständiges Dorf und wurde im Jahr 1850 gemeinsam mit anderen Vororten in die Stadt Wien eingemeindet"}, {"kategorie": "", "text": "Der Name Gumpendorf leitet sich wahrscheinlich von einem alten Personennamen oder von einem kleinen Bach (Gumpen) ab, der durch das Gebiet floss"}, {"kategorie": "", "text": "Im 18. Jahrhundert war Gumpendorf für seine Vorstadtpalais und Gärten bekannt, die wohlhabende Wiener Bürger angezogen haben"}, {"kategorie": "", "text": "Gumpendorf ist heute geprägt von einer Mischung aus historischen Bauten und modernen Einrichtungen. Viele Gebäude aus dem 18. und 19. Jahrhundert, darunter [[Gründerzeithäuser]], sind erhalten geblieben und verleihen dem Stadtteil seinen charakteristischen Charme"}]'::jsonb, ''),
  ('strozzigrund', 'Strozzigrund', '', '', '', '', 'Strozzigrund', '[{"kategorie": "allg.", "text": "Stadtteil im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Der Stadtteil Strozzigrund hat seinen Namen von der italienischen Adelsfamilie Strozzi, die im 17. Jahrhundert in Wien ansässig wurde. Die Familie war eine der wohlhabendsten und einflussreichsten Familien Wiens und besaß große Ländereien und Immobilien in der Stadt. Einer der bekanntesten Vertreter der Familie war Feldmarschall Graf Peter Strozzi, der im Dienst der Habsburger stand"}, {"kategorie": "", "text": "Das Gebiet, das heute als Strozzigrund bekannt ist, wurde im 17. und 18. Jahrhundert allmählich urbanisiert. Ursprünglich bestanden hier große Gärten und Weingärten, die im Laufe der Zeit durch Wohnbebauung ersetzt wurden. Die Familie Strozzi ließ hier das als Strozzihof genannte Palais erbauen, das heute nicht mehr existiert, aber dem Gebiet seinen Namen gab"}, {"kategorie": "", "text": "Der Strozzigrund ist heute ein dicht besiedeltes Wohngebiet, das durch eine Mischung aus historischen Gebäuden aus dem 18. und 19. Jahrhundert geprägt ist. Viele der Häuser sind gut erhaltene Beispiele der Wiener [[Gründerzeitarchitektur]], die das Stadtbild dieses Teils der Josefstadt dominieren."}]'::jsonb, ''),
  ('leachnfoeoed', 'Leachnfööd', '', '', '', '', 'Lerchenfeld', '[{"kategorie": "allg.", "text": "historischer Stadtteil in Wien, der sich heute über Teile des 7. Wiener Gemeindebezirks ([[Neubau]]) und des 8. Bezirks ([[Josefstadt]]) erstreckt"}, {"kategorie": "", "text": "Der Name \"Lerchenfeld\" leitet sich von den Lerchen ab, die früher auf den Feldern dieses Gebiets nisteten. Im Mittelalter war das Lerchenfeld ein unbebautes Land außerhalb der Stadtmauern von Wien, das hauptsächlich landwirtschaftlich genutzt wurde. Erst im 17. und 18. Jahrhundert begann die Bebauung des Gebiets, als sich das Stadtgebiet von Wien zunehmend ausdehnte"}, {"kategorie": "", "text": "Während der Wiener Türkenbelagerungen im 16. und 17. Jahrhundert war das Lerchenfeld ein strategisch wichtiges Gebiet, da es in unmittelbarer Nähe zu den Stadtmauern lag. Nach der zweiten Türkenbelagerung 1683 wurden die freien Flächen nach und nach besiedelt, und das Gebiet entwickelte sich zu einem Vorort von Wien"}, {"kategorie": "", "text": "Das Lerchenfeld ist heute geprägt von einer Mischung aus historischer Bausubstanz und moderner Architektur. Viele der Gebäude stammen aus der [[Gründerzeit]] des späten 19. Jahrhunderts und sind typisch für die Wiener Architektur dieser Epoche. Diese Häuser sind oft reich verziert und spiegeln den Wohlstand der damaligen Bewohner wider"}, {"kategorie": "", "text": "Einen besonderen architektonischen Akzent im Lerchenfeld setzt die [[Pfarrkirche]] Altlerchenfeld, eine imposante neogotische Kirche, die im 19. Jahrhundert erbaut wurde und als eines der markantesten Bauwerke des Viertels gilt."}]'::jsonb, ''),
  ('braadnfoeoed', 'Braadnfööd', '', '', '', '', 'Breitenfeld', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Breitenfeld war ursprünglich eine ländliche Gegend außerhalb der damaligen Stadtgrenzen Wiens. Im Laufe des 18. und 19. Jahrhunderts wurde das Gebiet urbanisiert, da Wien expandierte und immer mehr Vororte in die Stadt eingegliedert wurden. Die offizielle Eingemeindung des Gebiets in die Stadt Wien erfolgte im Jahr 1850, als der Bezirk Josefstadt gebildet wurde"}, {"kategorie": "", "text": "Der Name Breitenfeld leitet sich vermutlich von den offenen Feldern ab, die sich ursprünglich in diesem Gebiet erstreckten. Diese Felder boten Platz für die Entwicklung des Viertels, das schnell zu einem dicht bebauten Stadtteil mit Wohnhäusern, Schulen und Kirchen wurde"}, {"kategorie": "", "text": "Breitenfeld ist vor allem durch seine charakteristischen Gebäude aus der [[Gründerzeit]] geprägt. Viele der Wohnhäuser und öffentlichen Gebäude stammen aus dem späten 19. Jahrhundert und sind typische Beispiele für den architektonischen Stil dieser Epoche. Die Straßen des Viertels sind von beeindruckenden Fassaden, hohen Decken und kunstvoll gestalteten Portalen gesäumt, die den Wohlstand und die städtische Entwicklung Wiens in dieser Zeit widerspiegeln"}, {"kategorie": "", "text": "Ein zentrales Wahrzeichen des Viertels ist die [[Pfarrkirche]] Breitenfeld, die in den Jahren 1894 bis 1898 erbaut wurde. Die Kirche ist ein herausragendes Beispiel für den neuromanischen Baustil in Wien und ein wichtiges religiöses Zentrum für die Gemeinde."}]'::jsonb, ''),
  ('laamgruabm', 'Laamgruabm', '', '', '', '', 'Laimgrube', '[{"kategorie": "allg.", "text": "historischer Stadtteil in Wien, der heute Teil des 6. Wiener Gemeindebezirks ([[Mariahilf]]) ist"}, {"kategorie": "", "text": "Der Name \"Laimgrube\" stammt von den früheren Lehmgruben (dialektal \"Laim\"), die in diesem Gebiet für die Ziegelproduktion genutzt wurden. Der Stadtteil Laimgrube war im 18. und 19. Jahrhundert ein bedeutendes Handwerks- und Gewerbegebiet, das durch seine Nähe zu Wien eine schnelle Urbanisierung erlebte"}, {"kategorie": "", "text": "Im Laufe der Zeit wurden die Lehmgruben erschöpft, und das Gebiet erlebte eine zunehmende Bebauung mit Wohnhäusern, was zur Entstehung eines dichten städtischen Viertels führte. Die Nähe zur Wiener Innenstadt und die gute Anbindung an Verkehrswege förderten das Wachstum des Stadtteils. 1850 wurde die Laimgrube offiziell nach Wien eingemeindet und Teil des neu geschaffenen 6. Bezirks ([[Mariahilf]])"}, {"kategorie": "", "text": "Die historische Bedeutung der Laimgrube liegt vor allem in ihrer Rolle als frühes Industrie- und Handwerkszentrum von Wien. Die ehemaligen Ziegelbrennereien und Handwerksbetriebe trugen maßgeblich zur wirtschaftlichen Entwicklung der Stadt bei"}, {"kategorie": "", "text": "Das Gebiet der ehemaligen Laimgrube ist heute geprägt von einer Mischung aus historischen Bauten und modernen Gebäuden. Viele der Häuser stammen aus dem 19. Jahrhundert und spiegeln den Baustil der [[Gründerzeit]] wider. Die dichte Bebauung und die schmalen Straßen sind typisch für die Wiener Vororte dieser Zeit, die sich schnell entwickelten, um den Bedarf an Wohnraum und Gewerbeflächen zu decken"}]'::jsonb, ''),
  ('magdalenanviatl', 'Magdalenanviatl', '', '', '', '', 'Magdalenenviertel', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 6. Wiener Gemeindebezirk ([[Mariahilf]])"}, {"kategorie": "", "text": "Das Magdalenenviertel hat eine lange Geschichte, die bis ins Mittelalter zurückreicht. Ursprünglich befand sich hier die Magdalenenkapelle, eine der ältesten Kapellen im Bereich der heutigen Inneren Stadt und ihrer Umgebung. Diese Kapelle war der heiligen Maria Magdalena geweiht und gab dem Viertel seinen Namen. Das Gebiet war damals überwiegend ländlich geprägt und lag außerhalb der Stadtmauern Wiens"}, {"kategorie": "", "text": "Mit der fortschreitenden Urbanisierung im 17. und 18. Jahrhundert entwickelte sich das Magdalenenviertel von einem ländlichen Vorort zu einem städtischen Wohngebiet. Nach der Eingemeindung in Wien im Jahr 1850 wurde das Viertel Teil des Bezirks Mariahilf"}, {"kategorie": "", "text": "Das Magdalenenviertel ist heute geprägt von einer Mischung aus historischer und moderner Architektur. Viele Gebäude stammen aus dem 19. Jahrhundert und sind typische Beispiele der Wiener [[Gründerzeitarchitektur]]. Diese Bauten sind oft reich verziert und tragen zu dem charakteristischen Erscheinungsbild des Viertels bei"}, {"kategorie": "", "text": "Die enge Bebauung und die verwinkelten Straßen des Viertels spiegeln die historische Entwicklung Wiens wider, bei der sich die Stadt immer mehr ausdehnte und die ehemaligen Vororte und ländlichen Gebiete in das städtische Gefüge integrierte. Trotz der Urbanisierung hat das Magdalenenviertel einen Teil seines historischen Charmes bewahrt"}]'::jsonb, ''),
  ('schbittlbeag', 'Schbittlbeag', '', '', '', '', 'Spittelberg', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 7. Wiener Gemeindebezirk ([[Neubau]])"}, {"kategorie": "", "text": "Bekannt für seine gut erhaltenen Biedermeierhäuser, verwinkelten Gassen und eine lebendige Kulturszene, zählt der Spittelberg zu den charmantesten und am besten erhaltenen historischen Vierteln Wiens. Heute ist der Spittelberg ein beliebtes Wohn- und Ausgehviertel und vor allem für seinen jährlichen Weihnachtsmarkt bekannt"}, {"kategorie": "", "text": "Der Name Spittelberg leitet sich vom \"Spital am Berge\" ab, einem 1675 gegründeten Siechenhaus, das ursprünglich in diesem Gebiet lag. Der Spittelberg entwickelte sich im 17. und 18. Jahrhundert zu einem dicht besiedelten Vorort Wiens. Aufgrund seiner Lage außerhalb der damaligen Stadtmauern war das Viertel lange Zeit ein Zufluchtsort für ärmere Bevölkerungsschichten, darunter Handwerker, Tagelöhner und Kleinhändler"}, {"kategorie": "", "text": "Im 18. Jahrhundert erlebte der Spittelberg einen wirtschaftlichen Aufschwung und wurde zu einem lebhaften Handwerks- und Gewerbegebiet. Die enge Bebauung mit kleinen, aber kunstvoll gestalteten Biedermeierhäusern prägt das Stadtbild bis heute. Im 19. Jahrhundert wurde das Viertel zunehmend urbanisiert, verlor jedoch nie seinen kleinteiligen, fast dörflichen Charakter"}, {"kategorie": "", "text": "Der Spittelberg ist heute bekannt für seine einzigartige Architektur, die vor allem durch die Biedermeierbauten geprägt ist. Die Gebäude aus dem 18. und frühen 19. Jahrhundert sind durch ihre schlichte Eleganz, verzierten Fassaden und malerischen Innenhöfe charakterisiert. Die engen, kopfsteingepflasterten Gassen verleihen dem Viertel einen besonderen Charme und lassen die historische Atmosphäre des alten Wiens wieder aufleben."}]'::jsonb, ''),
  ('schbittelau', 'Schbittelau', '', '', '', '', 'Spittelau', '[{"kategorie": "allg.", "text": "Stadtteil im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Der Name Spittelau ist besonders bekannt durch die [[Müllverbrennungsanlage]] Spittelau, die zu den markantesten Bauwerken der Stadt zählt. Spittelau liegt am Donaukanal und ist ein wichtiger Verkehrsknotenpunkt sowie ein markanter Standort für moderne Infrastruktur und Umwelttechnologie"}, {"kategorie": "", "text": "Der Name Spittelau leitet sich historisch von den Wörtern \"Spital\" und \"Au\" ab, wobei \"Spital\" auf das nahegelegene Hospital des Heiligen Geistes in Wien verweist und \"Au\" eine Flusslandschaft oder Flussaue bezeichnet. Ursprünglich war das Gebiet rund um Spittelau eine sumpfige Auenlandschaft entlang des Donaukanals. Mit der fortschreitenden Urbanisierung Wiens im 19. Jahrhundert wurde die Spittelau zunehmend bebaut und entwickelt"}, {"kategorie": "", "text": "Im Laufe der Zeit entwickelte sich Spittelau zu einem wichtigen Industriestandort, vor allem durch den Bau der Müllverbrennungsanlage, die im Jahr 1971 in Betrieb genommen wurde. Diese Anlage wurde nach einem Brand im Jahr 1987 von dem weltberühmten Künstler und Architekten Friedensreich Hundertwasser in seinem unverwechselbaren Stil neugestaltet und gilt heute als eines der bekanntesten Beispiele für umweltbewusste Architektur in Wien."}]'::jsonb, ''),
  ('schottnfoeoed', 'Schottnfööd', '', '', '', '', 'Schottenfeld', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 7. Wiener Gemeindebezirk ([[Neubau]])"}, {"kategorie": "", "text": "Der Name geht auf das [[Schottenstift]], ein bedeutendes Benediktinerkloster in Wien, zurück, das im 12. Jahrhundert von irischen Mönchen (fälschlicherweise oft als Schotten bezeichnet) gegründet wurde. Das Schottenstift besaß ausgedehnte Ländereien außerhalb der damaligen Stadtmauern, die als Schottenfelder bekannt waren. Diese Felder wurden zunächst landwirtschaftlich genutzt, bevor sie im 18. Jahrhundert zunehmend bebaut wurden"}, {"kategorie": "", "text": "Im Zuge der Expansion Wiens und der fortschreitenden Urbanisierung im 18. Jahrhundert begann die Besiedlung des Schottenfelds. Im Jahr 1850 wurde das Schottenfeld offiziell nach Wien eingemeindet und Teil des neu geschaffenen 7. Bezirks, Neubau. Mit der Eingemeindung entwickelte sich das Gebiet zu einem lebendigen Stadtteil mit einer Mischung aus Wohnhäusern, Handwerksbetrieben und kleinen Gewerben"}, {"kategorie": "", "text": "Schottenfeld ist geprägt von einer typischen Wiener Architektur, die vor allem durch Gebäude aus der [[Gründerzeit]] und dem Biedermeier dominiert wird. Die Straßen des Viertels sind von großen, repräsentativen Wohnhäusern gesäumt, die häufig mit kunstvollen Fassaden und schmiedeeisernen Balkonen versehen sind"}, {"kategorie": "", "text": "Besonders markant sind die engen Gassen und dicht bebauten Straßen, die das historische Wachstum und die Entwicklung des Viertels widerspiegeln. Viele der alten Handwerksbetriebe, die einst das wirtschaftliche Rückgrat des Schottenfelds bildeten, sind heute durch moderne Geschäfte, Cafés und Galerien ersetzt worden, die dem Viertel einen lebendigen und zeitgemäßen Charakter verleihen."}]'::jsonb, ''),
  ('oidleachnfoeoed', 'Oidleachnfööd', '', '', '', '', 'Altlerchenfeld', '[{"kategorie": "allg.", "text": "historischer Stadtteil in Wien, der sich heute über Teile des 7. Wiener Gemeindebezirks ([[Neubau]]) und des 8. Bezirks ([[Josefstadt]]) erstreckt"}, {"kategorie": "", "text": "Der Name Altlerchenfeld leitet sich von den ursprünglichen Feldern ab, auf denen sich Lerchen (Vögel) ansiedelten. Im Mittelalter war das Gebiet weitgehend unbebaut und wurde landwirtschaftlich genutzt"}, {"kategorie": "", "text": "Im 18. Jahrhundert erlebte Altlerchenfeld eine stärkere Urbanisierung, und es entstanden zahlreiche Wohnhäuser und Handwerksbetriebe. Das Viertel entwickelte sich zu einem dicht besiedelten Vorort von Wien. Mit der Eingemeindung in Wien im Jahr 1850 wurde Altlerchenfeld offiziell Teil der Stadt und in die neu geschaffenen Bezirke Neubau und Josefstadt integriert"}, {"kategorie": "", "text": "Altlerchenfeld zeichnet sich durch eine Mischung aus historischer Biedermeierarchitektur und Gebäuden aus der [[Gründerzeit]] aus. Viele der Wohnhäuser stammen aus dem 19. Jahrhundert und sind gut erhalten, was dem Viertel seinen charakteristischen Charme verleiht. Die engen, verwinkelten Gassen und die dicht aneinandergebauten Häuser sind typisch für die historische Entwicklung des Viertels"}, {"kategorie": "", "text": "Ein zentrales architektonisches Wahrzeichen des Viertels ist die [[Pfarrkirche]] Altlerchenfeld, eine imposante neogotische Kirche, die zwischen 1848 und 1857 erbaut wurde."}]'::jsonb, ''),
  ('westbaunviatl', 'Westbaunviatl', '', '', '', '', 'Westbahnviertel', '[{"kategorie": "allg.", "text": "Stadtteil im 7. Wiener Gemeindebezirk ([[Neubau]])"}, {"kategorie": "", "text": "Der Name leitet sich von der nahegelegenen Westbahn, einer wichtigen Eisenbahnverbindung in Österreich, ab. Das Viertel erstreckt sich in der Nähe des [[Westbahnhofs]], einem der zentralen Verkehrsknotenpunkte der Stadt"}, {"kategorie": "", "text": "Das Westbahnviertel entwickelte sich im Zuge des Ausbaus der Westbahnstrecke, die Wien mit dem westlichen Teil Österreichs und weiteren Teilen Europas verbindet. Der Wiener Westbahnhof wurde 1858 eröffnet und diente als zentraler Ausgangspunkt der Westbahnstrecke, die Wien mit Städten wie Linz, Salzburg und weiter nach Deutschland verbindet"}, {"kategorie": "", "text": "Das Westbahnviertel ist geprägt von einer typischen Wiener [[Gründerzeitarchitektur]]. Viele der Gebäude in diesem Viertel stammen aus der zweiten Hälfte des 19. Jahrhunderts und sind charakteristische Beispiele für die dichte, repräsentative Bebauung der Gründerzeit. Die Architektur ist oft durch prächtige Fassaden, hohe Decken und große Fenster geprägt"}, {"kategorie": "", "text": "Neben den historischen Wohnhäusern gibt es im Westbahnviertel auch zahlreiche gewerbliche und kulturelle Einrichtungen. Die Nähe zum Westbahnhof macht das Viertel zu einem zentralen Ort für Handel und Dienstleistungen"}]'::jsonb, ''),
  ('schlossquadraad', 'Schlossquadraad', '', '', '', '', 'Schlossquadrat', '[{"kategorie": "allg.", "text": "charmantes und historisch bedeutendes Areal im 5. Wiener Gemeindebezirk ([[Margareten]])"}, {"kategorie": "", "text": "Es besteht aus mehreren Gebäuden und einem Innenhof und ist bekannt für seine lebendige Gastronomieszene, historische Architektur und kulturellen Veranstaltungen. Der Name \"Schlossquadrat\" leitet sich von der quadratischen Anordnung der Gebäude und dem historischen Ambiente des Viertels ab"}, {"kategorie": "", "text": "Das Schlossquadrat hat eine lange Geschichte, die bis ins 18. Jahrhundert zurückreicht. Das Areal war ursprünglich Teil eines größeren Anwesens, das im Laufe der Zeit in kleinere Parzellen aufgeteilt und bebaut wurde. Der historische Kern des Schlossquadrats wurde durch den Bau eines Herrenhauses geprägt, das später durch Wohn- und Geschäftshäuser ergänzt wurde"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wurde das Schlossquadrat mehrfach umgestaltet und renoviert, wobei sein historischer Charakter weitgehend bewahrt blieb. Es entwickelte sich zu einem beliebten Treffpunkt im Bezirk Margareten, insbesondere aufgrund der zentralen Lage und des besonderen Flairs, das durch die historischen Gebäude und den geschützten Innenhof vermittelt wird"}, {"kategorie": "", "text": "Die Architektur des Schlossquadrats spiegelt die Entwicklung Wiens im Laufe der Jahrhunderte wider, von der Residenzstadt über die Zeit der industriellen Revolution bis hin zur modernen Großstadt. Die gut erhaltenen Fassaden und das Ensemble der Gebäude machen das Schlossquadrat zu einem bedeutenden Beispiel für die Architektur und Stadtentwicklung Wiens."}]'::jsonb, ''),
  ('matzleinsduaf', 'Matzleinsduaf', '', '', '', '', 'Matzleinsdorf', '[{"kategorie": "allg.", "text": "historischer Stadtteil in Wien, der heute Teil des 5. Wiener Gemeindebezirks ([[Margareten]]) und des 10. Bezirks ([[Favoriten]]) ist"}, {"kategorie": "", "text": "Der Name Matzleinsdorf geht auf den Ritter Matzilin zurück, der im 12. Jahrhundert in dieser Gegend lebte und dem Dorf seinen Namen gab. Das Dorf Matzleinsdorf entwickelte sich im Mittelalter zu einem kleinen landwirtschaftlichen Ort vor den Toren Wiens"}, {"kategorie": "", "text": "Im 17. und 18. Jahrhundert wurde das Gebiet zunehmend urbanisiert, da Wien expandierte und immer mehr Vororte in die Stadt eingegliedert wurden. Matzleinsdorf blieb jedoch lange Zeit ein eigenständiges Dorf und wurde erst 1850 gemeinsam mit anderen Vororten in Wien eingemeindet. Ab diesem Zeitpunkt entwickelte sich Matzleinsdorf schnell zu einem städtischen Gebiet"}, {"kategorie": "", "text": "Im 19. Jahrhundert wurden große Teile von Matzleinsdorf für den Bau von Wohnhäusern und Industrieanlagen genutzt, was zur urbanen Entwicklung des Gebiets beitrug. Der Bau des [[Wiener]] Südbahnhofs und des [[Matzleinsdorfer]] Bahnhofs (heute [[Matzleinsdorfer]] Platz) spielte eine wichtige Rolle in der Entwicklung des Viertels zu einem verkehrstechnisch bedeutenden Knotenpunkt"}, {"kategorie": "", "text": "Ein bedeutendes Bauwerk in Matzleinsdorf ist die [[Matzleinsdorfer]] Pfarrkirche, die auch unter dem Namen \"Kirche zur Heiligen Elisabeth\" bekannt ist. Diese Kirche, die im 19. Jahrhundert erbaut wurde, ist ein prägendes Element im Stadtteil und ein wichtiges religiöses Zentrum für die Gemeinde"}]'::jsonb, ''),
  ('reinprechtsduaf', 'Reinprechtsduaf', '', '', '', '', 'Reinprechtsdorf', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 5. Wiener Gemeindebezirk ([[Margareten]])"}, {"kategorie": "", "text": "Reinprechtsdorf hat eine lange Geschichte, die bis ins Mittelalter zurückreicht. Der Name leitet sich wahrscheinlich von einem Adligen namens Reinprecht ab, der das Dorf gegründet oder besessen hat. Das Dorf Reinprechtsdorf war über Jahrhunderte ein kleines, landwirtschaftlich geprägtes Dorf außerhalb der Stadtmauern Wiens"}, {"kategorie": "", "text": "Im Zuge der städtischen Expansion im 19. Jahrhundert wurde Reinprechtsdorf immer mehr in das städtische Gefüge integriert. Das Dorf wurde 1850 offiziell nach Wien eingemeindet und Teil des neu geschaffenen 5. Bezirks, Margareten. Die Industrialisierung und das schnelle Bevölkerungswachstum führten dazu, dass das ehemalige Dorf rasch urbanisiert und dicht bebaut wurde"}, {"kategorie": "", "text": "Reinprechtsdorf ist heute geprägt von einer dichten, urbanen Bebauung, die hauptsächlich aus Wohnhäusern aus der [[Gründerzeit]] besteht. Die Architektur ist typisch für die Wiener Vororte des 19. Jahrhunderts, mit mehrstöckigen Mietshäusern, die durch ihre Fassaden und Balkone geprägt sind. Diese Gebäude stammen meist aus dem späten 19. und frühen 20. Jahrhundert und spiegeln den Aufschwung und das Wachstum Wiens in dieser Zeit wider"}, {"kategorie": "", "text": "Das Viertel hat eine enge Straßenstruktur mit zahlreichen kleinen Geschäften, Cafés und Restaurants, die das Alltagsleben der Bewohner prägen. Der dichte, urbane Charakter von Reinprechtsdorf steht im Kontrast zu den ländlichen Ursprüngen des Dorfes, die heute kaum mehr sichtbar sind."}]'::jsonb, ''),
  ('nikoisduaf', 'Nikoisduaf', '', '', '', '', 'Nikolsdorf', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 5. Wiener Gemeindebezirk ([[Margareten]])"}, {"kategorie": "", "text": "Der Name Nikolsdorf leitet sich von Nikolaus Oláh, dem Erzbischof von Gran, ab, der im 16. Jahrhundert die Grundherrschaft über das Gebiet besaß. Das Dorf Nikolsdorf entstand im 17. Jahrhundert und war ursprünglich ein kleines, landwirtschaftlich geprägtes Dorf vor den Toren Wiens. Es wurde im Laufe der Jahrhunderte immer stärker in das städtische Gefüge integriert"}, {"kategorie": "", "text": "Im Zuge der städtischen Expansion und der Industrialisierung im 19. Jahrhundert erlebte Nikolsdorf eine rasche Urbanisierung. Das Dorf wurde 1850 nach Wien eingemeindet und Teil des neu geschaffenen 5. Bezirks ([[Margareten]]). Die ländliche Struktur wich zunehmend einer dichten Bebauung, und Nikolsdorf entwickelte sich zu einem urbanen Wohnviertel"}, {"kategorie": "", "text": "Nikolsdorf ist heute geprägt von einer Mischung aus historischer und moderner Architektur. Viele Gebäude stammen aus der [[Gründerzeit]] des 19. Jahrhunderts und sind typische Beispiele für die Wiener Architektur dieser Epoche. Die Bauten sind häufig mehrstöckige Mietshäuser mit kunstvoll gestalteten Fassaden und Innenhöfen."}]'::jsonb, ''),
  ('hundstuam', 'Hundstuam', '', '', '', '', 'Hundsturm', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 5. Wiener Gemeindebezirk ([[Margareten]])"}, {"kategorie": "", "text": "Der Name Hundsturm leitet sich vermutlich von einem ehemaligen Wehrturm ab, der im Mittelalter in diesem Gebiet stand und zur Verteidigung gegen Eindringlinge genutzt wurde"}, {"kategorie": "", "text": "Im 18. und 19. Jahrhundert wuchs Hundsturm, bedingt durch die zunehmende Urbanisierung Wiens, schnell. Das Dorf wurde 1850 gemeinsam mit anderen Vororten in die Stadt Wien eingemeindet und Teil des neu gegründeten Bezirks Margareten"}, {"kategorie": "", "text": "Das Viertel ist charakterisiert durch enge, verwinkelte Gassen und dicht aneinander gebaute Häuser, was auf die rasche Urbanisierung im 19. Jahrhundert zurückzuführen ist. Einige Teile von Hundsturm haben sich ihren historischen Charme bewahrt, während andere Bereiche durch moderne Bauprojekte erneuert wurden"}, {"kategorie": "", "text": "Heute ist Hundsturm ein dicht besiedeltes Wohngebiet, das für seine zentrale Lage und seine gute Anbindung an den Rest der Stadt geschätzt wird. Der Stadtteil hat eine hohe Lebensqualität und bietet eine Mischung aus historischem Flair und modernem städtischen Leben."}]'::jsonb, ''),
  ('freihausviatl', 'Freihausviatl', '', '', '', '', 'Freihausviertel', '[{"kategorie": "allg.", "text": "lebendiger und kulturell bedeutender Stadtteil im 4. Wiener Gemeindebezirk ([[Wieden]])"}, {"kategorie": "", "text": "Der Name \"Freihausviertel\" leitet sich vom historischen Freihaus auf der Wieden ab, einem großen Wohnkomplex, der im 17. Jahrhundert von der Fürstenfamilie Starhemberg errichtet wurde. Dieses Freihaus war ein Zentrum für Handwerker und kleine Gewerbetreibende und bot Wohnraum für eine Vielzahl von Menschen aus unterschiedlichen sozialen Schichten. Aufgrund der besonderen Rechtsstellung der Freihausbewohner waren sie von bestimmten städtischen Abgaben und Pflichten befreit, was dem Viertel seinen Namen gab"}, {"kategorie": "", "text": "Das Freihaus selbst wurde im 19. Jahrhundert abgerissen, um Platz für neue Straßen und Bebauungen zu schaffen, doch der Name blieb erhalten und prägt bis heute das Image des Viertels"}, {"kategorie": "", "text": "Das Freihausviertel ist geprägt von einer Mischung aus historischer und moderner Architektur. Viele der Gebäude stammen aus der [[Gründerzeit]] und sind typische Beispiele für die Wiener Architektur des 19. Jahrhunderts. Diese Bauten zeichnen sich durch ihre prachtvollen Fassaden, hohen Decken und großen Fenster aus, die dem Viertel seinen besonderen Charme verleihen"}, {"kategorie": "", "text": "In den letzten Jahrzehnten wurden viele dieser historischen Gebäude renoviert und in moderne Wohn- und Geschäftsräume umgewandelt. Das Viertel hat sich zu einem kreativen Hotspot entwickelt, in dem Kunst, Kultur und Design eine zentrale Rolle spielen"}]'::jsonb, ''),
  ('schleifmueueviatl', 'Schleifmüüviatl', '', '', '', '', 'Schleifmühlviertel', '[{"kategorie": "allg.", "text": "\"kleiner, aber lebendiger Stadtteil im 4. Wiener Gemeindebezirk ([[Wieden]])\". Das Viertel ist bekannt für seine kreative Atmosphäre, seine kulturellen Angebote und seine Mischung aus historischen und modernen Gebäuden. Das Schleifmühlviertel grenzt an den berühmten Naschmarkt und ist heute ein beliebtes Wohn- und Ausgehviertel"}, {"kategorie": "", "text": "Der Name \"Schleifmühlviertel\" leitet sich von der ehemaligen Schleifmühle ab, die in diesem Gebiet im 16. Jahrhundert betrieben wurde. Diese Mühle war eine von mehreren, die entlang des [[Wienflusses]] betrieben wurden, um Werkzeuge und Waffen zu schärfen, also zu \"schleifen\". Die Mühle prägte das Gebiet und gab dem Viertel seinen Namen"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte entwickelte sich das Gebiet rund um die Schleifmühle weiter, und es entstanden Wohnhäuser, Handwerksbetriebe und kleinere Geschäfte. Besonders im 19. Jahrhundert, während der Gründerzeit, erlebte das Viertel eine starke Urbanisierung, und viele der heute noch erhaltenen Gebäude stammen aus dieser Epoche"}, {"kategorie": "", "text": "Die Architektur des Viertels zeichnet sich durch prachtvolle Fassaden, hohe Decken und großzügige Wohnungen aus, die typisch für die Wiener [[Gründerzeitarchitektur]] sind. Viele der Gebäude wurden im Laufe der letzten Jahrzehnte renoviert und modernisiert, was dem Viertel eine attraktive Mischung aus Alt und Neu verleiht"}, {"kategorie": "", "text": "Die Straßen des Schleifmühlviertels sind oft schmal und gepflastert, was dem Viertel einen besonderen Charme verleiht. Kleine Plätze und Innenhöfe tragen zur ruhigen, fast dörflichen Atmosphäre bei, die trotz der zentralen Lage in Wien bewahrt wurde"}]'::jsonb, ''),
  ('eadbeag', 'Eadbeag', '', '', '', '', 'Erdberg', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Erdberg liegt im südöstlichen Teil des 3. Bezirks und grenzt an mehrere andere Wiener Stadtteile, darunter an das [[Weißgerberviertel]] im Norden, [[St]]. Marx im Süden und das Zentrum von [[Landstraße]] im Westen. Der [[Donaukanal]], eine wichtige Wasserstraße, bildet die natürliche Grenze im Osten und trennt Erdberg von den östlichen Bezirken der Stadt"}, {"kategorie": "", "text": "Der Name \"Erdberg\" leitet sich möglicherweise vom mittelhochdeutschen Begriff \"Erdberg\" oder \"Erdburg\" ab, was eine Erdaufschüttung oder einen natürlichen Hügel beschreibt, auf dem sich im Mittelalter eine befestigte Siedlung befunden haben könnte. Die erste urkundliche Erwähnung des Gebiets geht auf das 12. Jahrhundert zurück, als es sich noch um eine ländliche Siedlung handelte"}, {"kategorie": "", "text": "Im 19. Jahrhundert wurde Erdberg zusammen mit anderen Vororten in die Stadt Wien eingemeindet, was zu einer raschen Urbanisierung führte. Viele der Gebäude aus dieser Zeit prägen noch heute das Stadtbild von Erdberg, insbesondere die typischen Wiener [[Gründerzeithäuser]]. Erdberg war auch Standort von Industrie- und Gewerbebetrieben, die zur wirtschaftlichen Entwicklung des Viertels beitrugen"}, {"kategorie": "", "text": "Erdberg ist reich an kulturellen und historischen Stätten. Eine der bekanntesten Sehenswürdigkeiten sind die [[Gasometer]], vier riesige Gasbehälter, die Ende des 19. Jahrhunderts gebaut wurden und heute als Wohn-, Einkaufs- und Veranstaltungszentrum genutzt werden. Diese außergewöhnlichen Gebäude sind ein Symbol für die industrielle Vergangenheit und die moderne Entwicklung Wiens"}]'::jsonb, ''),
  ('weissgeabaviatl', 'Weissgeabaviatl', '', '', '', '', 'Weißgerberviertel', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Der Name \"Weißgerberviertel\" leitet sich von den Weißgerbern ab, die sich im 17. und 18. Jahrhundert in diesem Gebiet ansiedelten. Diese Handwerker spezialisierten sich auf die Bearbeitung von Leder und die Gerbung von Häuten, wobei sie das Leder weiß machten, was zu dem Namen \"Weißgerber\" führte"}, {"kategorie": "", "text": "Das Weißgerberviertel liegt im nördlichen Teil des 3. Bezirks und grenzt an den [[Donaukanal]], der die östliche Grenze bildet. Im Westen grenzt es an den Stadtteil [[Erdberg]] und im Süden an das Gebiet des ehemaligen Vorortes [[Landstraße]]. Es erstreckt sich von der [[Ungargasse]] im Süden bis zum Donaukanal im Norden und vom [[Stadtpark]] im Westen bis zur Grenze des Bezirks Landstraße im Osten"}, {"kategorie": "", "text": "Das Viertel entstand im 17. Jahrhundert, als die Gerberzunft begann, sich außerhalb der damaligen Stadtmauern Wiens niederzulassen. Das Gebiet war ideal für das Handwerk der Gerber, da der nahegelegene Donaukanal Wasser für die Lederbearbeitung lieferte. Im Laufe der Zeit wuchs die Siedlung und entwickelte sich zu einem bedeutenden Handwerks- und Industriegebiet"}, {"kategorie": "", "text": "Im Jahr 1850 wurde das Weißgerberviertel zusammen mit anderen Vororten in die Stadt Wien eingemeindet und in den 3. Bezirk integriert. Das Weißgerberviertel ist heute vor allem für seine Mischung aus historischer und moderner Architektur bekannt"}]'::jsonb, ''),
  ('ungargossn', 'Ungargossn', '', '', '', '', 'Ungargasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Die Ungargasse beginnt am [[Stadtpark]], einem der größten und bekanntesten Parks Wiens, und verläuft in südöstlicher Richtung durch den Bezirk Landstraße. Sie endet in der Nähe des [[Rennweg]], einer weiteren bedeutenden Straße des Bezirks. Die Straße ist etwa 1,6 Kilometer lang und durchquert mehrere wichtige Teile des Bezirks, darunter das [[Botschaftsviertel]], in dem sich viele ausländische Botschaften befinden"}, {"kategorie": "", "text": "Die Ungargasse hat ihren Namen vermutlich von der früheren Route, die von Wien nach Ungarn führte, da sie in Richtung Südosten, also in Richtung Ungarn, verläuft"}, {"kategorie": "", "text": "Mit der Erweiterung Wiens und der Eingemeindung der Vororte im 19. Jahrhundert entwickelte sich die Ungargasse zu einer städtischen Hauptstraße. In dieser Zeit entstanden viele der prunkvollen Gebäude, die heute das Bild der Ungargasse prägen"}, {"kategorie": "", "text": "Die Ungargasse ist Teil des sogenannten [[Botschaftsviertels]], in dem viele ausländische Botschaften untergebracht sind. Die eleganten Gebäude aus dem 19. und frühen 20. Jahrhundert tragen zum internationalen Flair der Gegend bei"}]'::jsonb, ''),
  ('botschoftsviatl', 'Botschoftsviatl', '', '', '', '', 'Botschaftsviertel', '[{"kategorie": "allg.", "text": "prestigeträchtiger und historisch bedeutender Teil des 3. Wiener Gemeindebezirks ([[Landstraße]])"}, {"kategorie": "", "text": "Es wird so genannt, weil sich hier eine hohe Konzentration ausländischer Botschaften und diplomatischer Vertretungen befindet. Das Viertel zeichnet sich durch seine repräsentativen Bauten, eleganten Wohnhäuser und die Nähe zu einigen der wichtigsten kulturellen und historischen Sehenswürdigkeiten der Stadt aus"}, {"kategorie": "", "text": "Das Botschaftsviertel liegt im südöstlichen Teil der Wiener Innenstadt und erstreckt sich rund um die [[Ungargasse]], den [[Rennweg]] und die [[Prinz-Eugen-Straße]]. Es grenzt an den Wiener [[Stadtpark]] im Norden und erstreckt sich bis zum [[Schloss]] Belvedere im Süden"}, {"kategorie": "", "text": "Das Botschaftsviertel hat seine Wurzeln im 19. Jahrhundert, als Wien eine bedeutende Rolle als Hauptstadt des Habsburgerreiches spielte. In dieser Zeit wurden viele der eleganten Palais und Stadtvillen errichtet, die heute als Botschaftsgebäude genutzt werden (die deutsche Botschaft in Wien ist im [[Palais]] Metternich untergebracht, die italienische Botschaft im [[Palais]] Sternberg, die iranische Botschaft im [[Palais]] Schwarzenberg und die russische Botschaft im [[Nassaupalais]], in einem monumentalen Bauwerk an der [[Reisnerstraße]], das 1890 im Neorenaissance-Stil errichtet wurde. Es ist eines der eindrucksvollsten Botschaftsgebäude in Wien)"}]'::jsonb, ''),
  ('reisnaschdrossn', 'Reisnaschdrossn', '', '', '', '', 'Reisnerstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\".  2. Sie verläuft in einem zentralen Bereich des sogenannten [[Botschaftsviertels]] und ist bekannt für ihre zahlreichen historischen Gebäude und diplomatischen Vertretungen. Die Reisnerstraße verbindet den Bereich um den [[Stadtpark]] mit dem Gebiet rund um das [[Schloss]] Belvedere, was sie zu einer strategisch und kulturell wichtigen Straße in Wien macht"}, {"kategorie": "", "text": "Mit dem Ausbau Wiens im 19. Jahrhundert und der Ansiedlung zahlreicher Botschaften und diplomatischer Vertretungen entwickelte sich die Reisnerstraße zu einer wichtigen Adresse im Wiener Stadtbild. Die dort errichteten Gebäude spiegeln den Reichtum und die Bedeutung Wiens als internationale Metropole wider"}, {"kategorie": "", "text": "Die Reisnerstraße ist ein wichtiger Bestandteil des Wiener Botschaftsviertels und spiegelt die internationale Bedeutung Wiens als diplomatisches und kulturelles Zentrum wider. Mit ihrer exklusiven Lage und ihrer reichen Geschichte ist die Reisnerstraße eine der prestigeträchtigsten Straßen in Wien."}]'::jsonb, ''),
  ('rennweg', 'Rennweg', '', '', '', '', 'Rennweg', '[{"kategorie": "allg.", "text": "\"bedeutende Straße in Wien, die durch den 3. Wiener Gemeindebezirk ([[Landstraße]]) führt\""}, {"kategorie": "", "text": "Sie ist eine der ältesten und längsten Straßen des Bezirks und verbindet die Wiener Innenstadt mit dem südöstlichen Teil der Stadt"}, {"kategorie": "", "text": "Der Rennweg hat eine lange und reiche Geschichte, die bis ins Mittelalter zurückreicht. Ursprünglich war er eine wichtige Verbindung zwischen der Wiener Innenstadt und den ländlichen Gebieten im Südosten der Stadt. Der Name \"Rennweg\" leitet sich vermutlich von seiner ursprünglichen Funktion als Rennbahn für Pferderennen ab, die in diesem Bereich stattfanden"}, {"kategorie": "", "text": "Mit der Erweiterung Wiens und der Errichtung repräsentativer Gebäude entlang des Rennwegs gewann die Straße an Bedeutung. Der Bau des [[Schlosses]] Belvedere durch Prinz Eugen von Savoyen im 18. Jahrhundert verlieh dem Rennweg zusätzliche Bedeutung und zog den Adel und wohlhabende Bürger an, die entlang der Straße prächtige Stadtpaläste errichteten (siehe [[Palais Metternich]])"}, {"kategorie": "", "text": "Am Rennweg befinden sich auch mehrere bedeutende Kirchen, darunter die [[Salesianerkirche]], eine barocke Kirche, die im 18. Jahrhundert erbaut wurde."}]'::jsonb, ''),
  ('salesianakiachn', 'Salesianakiachn', '', '', '', '', 'Salesianerkirche', '[{"kategorie": "allg.", "text": "\"barocke römisch-katholische Kirche im 3. Wiener Gemeindebezirk ([[Landstraße]]), auch bekannt als \"Kirche der Heimsuchung Mariens\""}, {"kategorie": "", "text": "Sie befindet sich am [[Rennweg]] 10 und ist Teil des [[Salesianerinnenklosters]], das im 18. Jahrhundert gegründet wurde"}, {"kategorie": "", "text": "Die Salesianerkirche und das angrenzende Kloster wurden 1717 von Kaiserin Wilhelmine Amalie, der Witwe von [[Kaiser]] Joseph I., gestiftet. Die Kaiserin zog sich nach dem Tod ihres Mannes in das Kloster zurück und unterstützte die Salesianerinnen, eine Ordensgemeinschaft, die dem heiligen Franz von Sales geweiht ist"}, {"kategorie": "", "text": "Die Salesianerkirche ist ein herausragendes Beispiel für die barocke Sakralarchitektur in Wien. Sowohl die äußere Erscheinung als auch die Innenausstattung der Kirche sind reich an barocken Elementen, die typisch für diese Epoche sind"}, {"kategorie": "", "text": "Der Innenraum der Salesianerkirche ist reich mit barocken Altären, Fresken und Skulpturen ausgestattet. Besonders hervorzuheben ist der Hochaltar, der eine Darstellung der Heimsuchung Mariens zeigt. Die kunstvollen Stuckarbeiten und die prächtigen Fresken an den Decken und Wänden tragen zur spirituellen und ästhetischen Atmosphäre der Kirche bei."}]'::jsonb, ''),
  ('salesianerinnenkloosta', 'Salesianerinnenkloosta', '', '', '', '', 'Salesianerinnenkloster', '[{"kategorie": "allg.", "text": "bedeutendes Kloster der römisch-katholischen Ordensgemeinschaft der Salesianerinnen, das sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) befindet"}, {"kategorie": "", "text": "Das Kloster wurde im frühen 18. Jahrhundert gegründet und ist eng mit der Geschichte der Habsburger Monarchie verbunden. Es liegt am Rennweg 10, unmittelbar neben der [[Salesianerkirche]], die Teil des Klosterkomplexes ist"}, {"kategorie": "", "text": "Die Gründung des Klosters wurde von Kaiserin Wilhelmine Amalie, der Witwe von [[Kaiser]] Joseph I., initiiert, die eine enge Verbindung zur Spiritualität und den Idealen der Salesianerinnen hatte. Die Salesianerinnen, ein kontemplativer Orden, der nach den Lehren des heiligen Franz von Sales gegründet wurde, widmeten sich dem Gebet, der Erziehung und der Pflege von Bedürftigen"}, {"kategorie": "", "text": "Das Salesianerinnenkloster ist ein typisches Beispiel für die klösterliche Architektur des Barock in Wien. Der Klosterkomplex umfasst mehrere Gebäude, darunter die Salesianerkirche, Wohngebäude für die Ordensfrauen und Gemeinschaftsräume."}]'::jsonb, ''),
  ('schlochthausschdrossn', 'Schlochthausschdrossn', '', '', '', '', 'Schlachthausstraße', '[{"kategorie": "allg.", "text": "\"Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie liegt in einem historisch bedeutenden Gebiet, das eng mit der Geschichte der Wiener Fleischversorgung und der städtischen Infrastruktur verbunden ist. Die Straße hat ihren Namen von den ehemaligen Schlachthöfen und Fleischmarkthallen, die sich in diesem Gebiet befanden und über viele Jahre eine zentrale Rolle in der Lebensmittelversorgung der Stadt spielten"}, {"kategorie": "", "text": "Im Zuge der Industrialisierung und des Bevölkerungswachstums im 19. Jahrhundert wurde die Notwendigkeit einer zentralisierten Fleischversorgung in Wien immer dringlicher. 1879 wurde in diesem Bereich der städtische Zentralviehmarkt mit angeschlossenen Schlachthäusern und Fleischmarkthallen errichtet, um die hygienischen Standards zu verbessern und eine effizientere Verteilung von Fleischprodukten zu gewährleisten"}, {"kategorie": "", "text": "Die Schlachthausstraße entwickelte sich rasch zu einem wichtigen Zentrum der Wiener Fleischindustrie. Hier wurden Tiere geschlachtet, Fleisch verarbeitet und an verschiedene Märkte der Stadt geliefert. Die Straße war von Industriebauten, Werkstätten und den Wohnhäusern der Arbeiter geprägt, die in den Schlachthöfen beschäftigt waren"}, {"kategorie": "", "text": "Die Schlachthausstraße hat sich im Laufe der Jahre von einem industriellen Zentrum zu einem gemischten Gebiet mit Wohn- und Gewerbenutzung entwickelt. Trotz der Veränderungen hat die Straße ihren historischen Charakter als wichtiger Teil der städtischen Infrastruktur bewahrt."}]'::jsonb, ''),
  ('fasanviatl', 'Fasanviatl', '', '', '', '', 'Fasanviertel', '[{"kategorie": "allg.", "text": "Stadtviertel im 3. Wiener Gemeindebezirk ([[Landstraße]]), das sich durch seine ruhige Wohnatmosphäre, seine historische Architektur und seine zentrale Lage auszeichnet"}, {"kategorie": "", "text": "Das Fasanviertel liegt im südwestlichen Teil des 3. Bezirks und wird im Norden von der [[Landstraßer]] Hauptstraße und im Osten vom [[Rennweg]] begrenzt. Im Westen grenzt das Viertel an den [[Schwarzenbergplatz]] und die [[Prinz-Eugen-Straße]], die zum [[Schloss]] Belvedere führt. Der südliche Teil des Fasanviertels reicht bis zur [[Arsenalstraße]])"}, {"kategorie": "", "text": "Das Fasanviertel hat seinen Namen von der Fasanfabrik, einer ehemaligen Fasanenzucht, die sich im 18. Jahrhundert auf diesem Gebiet befand. Das Viertel entwickelte sich im 19. und frühen 20. Jahrhundert zu einem gehobenen Wohngebiet, das von der Wiener Bürgerschaft und dem Adel geschätzt wurde"}, {"kategorie": "", "text": "Mit der Urbanisierung Wiens im 19. Jahrhundert wurde das Gebiet um das Fasanviertel zunehmend bebaut. Die Nähe zu bedeutenden Gebäuden wie dem Schloss Belvedere und den großzügigen Parks machte das Viertel zu einer beliebten Wohngegend für wohlhabende Bürger"}, {"kategorie": "", "text": "Das Fasanviertel liegt in der Nähe mehrerer großer Grünflächen, darunter der [[Botanische]] Garten der Universität Wien und die Gärten des [[Schlosses]] Belvedere. Diese Parks bieten den Bewohnern des Viertels Erholungsmöglichkeiten und tragen zur hohen Lebensqualität bei."}]'::jsonb, ''),
  ('fasangossn', 'Fasangossn', '', '', '', '', 'Fasangasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 3. Wiener Gemeindebezirk ([[Landstraße]]), die sich durch ihre historische Bedeutung, zentrale Lage und vielfältige Architektur auszeichnet. Sie verläuft vom [[Rennweg]] bis zur [[Landstraßer]] Hauptstraße und grenzt an das [[Fasanviertel]], eines der beliebten Wohngebiete im 3. Bezirk\""}, {"kategorie": "", "text": "Die Fasangasse hat ihren Namen von der Fasanfabrik, die sich in der Nähe des heutigen Fasanviertels befand. Diese Anlage war ursprünglich ein Ort zur Zucht von Fasanen für die kaiserlichen Jagden und hat dem gesamten Viertel seinen Namen gegeben"}, {"kategorie": "", "text": "Die Nähe zu bedeutenden Bauten wie dem [[Schloss]] Belvedere und die Anbindung an wichtige Verkehrswege machten die Fasangasse zu einer begehrten Adresse im 19. und frühen 20. Jahrhundert. Viele der Gebäude, die entlang der Straße errichtet wurden, stammen aus der [[Gründerzeit]] und dem Jugendstil und sind bis heute gut erhalten."}]'::jsonb, ''),
  ('arsenalschdrossn', 'Arsenalschdrossn', '', '', '', '', 'Arsenalstraße', '[{"kategorie": "allg.", "text": "\"Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie verläuft entlang des [[Wiener]] Arsenals, einem historischen Militärkomplex, der heute unter anderem das [[Heeresgeschichtliche]] Museum und verschiedene Büro- und Bildungseinrichtungen beherbergt. Die Straße ist nach diesem bedeutenden historischen Komplex benannt und spielt eine wichtige Rolle als Verkehrsverbindung im südöstlichen Teil des Bezirks"}, {"kategorie": "", "text": "Die Arsenalstraße wurde nach dem Bau des Wiener Arsenals im 19. Jahrhundert angelegt und diente ursprünglich als Erschließungsstraße für den militärischen Komplex. Mit der zunehmenden Urbanisierung Wiens und der Modernisierung der Infrastruktur im 19. und 20. Jahrhundert entwickelte sich die Arsenalstraße zu einer wichtigen Verbindung zwischen dem Stadtzentrum und den südöstlichen Bezirken."}]'::jsonb, '')
